	if !errors.Is(err, childErr) || len(calls) != 2 || !strings.HasPrefix(calls[0], "command.start") || calls[1] != "command.wait" {
		t.Fatalf("err=%v calls=%v", err, calls)
	}
	assertNotExists(t, internal.DirectSessionsDir(f.featurePath))
}

