package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool
	var featureDir bool
	var all bool
	var printPath bool
	var command string

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open a worktree with an agent, command, or path query",
		Long: `Open a worktree and run the configured agent. With no args, shows an interactive picker.

Use --feature-dir to open the feature directory itself (orchestrator mode).
Use --all to create a tmux session with windows for every worktree in the feature.

Explicit non-agent modes (no picker):
  tws open <feature> <branch> --print-path
  tws open <feature> --feature-dir --print-path
  tws open <feature> <branch> --command nvim -- .
  tws open <feature> --feature-dir --command code -- --wait .

For leading-dash selectors, put all tws flags before an initial --:
  tws open --feature-dir --print-path -- -feature
  tws open --command nvim -- -feature -branch -- README.md
The initial -- escapes options while selector slots remain. Consume those
slots (even a selector literally named --) before another -- for child argv.

--print-path is a read-only query: exactly one verified absolute path.
In checkout mode a branch query requires that branch to be currently attached.
--command runs one executable with literal arguments after the post-selector --.
It never evaluates a shell command line or starts a follow-up shell, and does
not change agent_command.
Branch commands honor tmux preferences; feature-directory commands default
direct (explicit tmux is external-only). Use GUI wait flags to track lifetime.
A child cannot change your parent shell's directory.`,
		Args: func(cmd *cobra.Command, args []string) error {
			if printPath || cmd.Flags().Changed("command") {
				_, err := parseExplicitOpen(cmd, args, printPath, command, featureDir, useTmux, noTmux, noAgent, all)
				return err
			}
			return cobra.RangeArgs(0, 2)(cmd, args)
		},
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if printPath || cmd.Flags().Changed("command") {
				want := explicitOpenSelectorCount(featureDir)
				selectors, _, childMarker, err := splitExplicitOpenArgs(args, cmd.ArgsLenAtDash(), want)
				if err != nil || childMarker || len(selectors) >= want {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				args = selectors
			}
			switch len(args) {
			case 0:
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				ws, err = managedTemplateExecutionWorkspace(ws)
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				features, err := ws.ListFeaturesResolved()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return features, cobra.ShellCompDirectiveNoFileComp
			case 1:
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				context, err := resolveFeatureContext(ws, args[0])
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return internal.ListBranchesAt(context.FeaturePath), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// Checkout mode: delegate to checkout session flow
			if ws.Mode == internal.ModeCheckout {
				if all {
					return fmt.Errorf("--all not supported in checkout mode")
				}

				// --feature-dir handled before branch resolution
				if featureDir {
					if len(args) < 1 {
						return fmt.Errorf("usage: tws open <feature> --feature-dir")
					}
					feature := args[0]
					if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
						return gerr
					}
					fp, ferr := ws.ResolveFeaturePath(feature)
					if ferr != nil {
						return ferr
					}
					managed, ferr := internal.ManagedTemplateStatePresent(fp)
					if ferr != nil {
						return ferr
					}
					var managedCfg resolvedManagedConfig
					if managed {
						managedCfg, ferr = resolveManagedConfig(ws)
						if ferr != nil {
							return ferr
						}
						if ferr := internal.ValidateManagedOrchestratorContext(
							ws, feature, fp, managedCfg.AgentCommand,
						); ferr != nil {
							return ferr
						}
					}
					// §14.2a: no session, no terminal, while a reparent is
					// recorded for this feature.
					if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
						return rerr
					}
					if noAgent {
						fmt.Printf("cd %s\n", fp)
						return nil
					}
					return internal.WithCheckoutSessionLaunchIntent(ws, func() error {
						return internal.CheckoutFeatureDirSessionPreconditions(ws)
					}, func() error {
						fmt.Printf("Opening feature dir: %s\n", fp)
						// A feature directory is not a logical branch, so it
						// has no per-branch record; the workspace intent itself
						// remains live through the agent and shell.
						return openDirect(directOpenOpts{
							Path: fp, AgentCommand: managedCfg.AgentCommand,
						})
					})
				}

				return runCheckoutOpenResolved(ws, args, useTmux, noTmux, noAgent, cmd.Flags(), nil)
			}
			// Handle --all: tmux session with all worktrees
			if all {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --all")
				}
				feature := args[0]
				ws, err = managedTemplateWorkspaceForFeature(ws, feature)
				if err != nil {
					return err
				}
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				resolved, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					return resolveErr
				}
				featurePath := resolved
				admission, err := featureRenameAdmissionAt(ws, feature)
				if err != nil {
					return err
				}
				defer func() { retErr = errors.Join(retErr, admission.Release()) }()
				if managed, managedErr := internal.ManagedTemplateStatePresent(resolved); managedErr != nil {
					return managedErr
				} else if managed {
					managedCfg, err := resolveManagedConfig(ws)
					if err != nil {
						return err
					}
					if err := internal.ValidateManagedOrchestratorContext(
						ws, feature, featurePath, managedCfg.AgentCommand,
					); err != nil {
						return err
					}
					if _, err := syncManagedAndLegacyInjectAll(
						cmd, ws, feature, featurePath,
						managedInjectTarget{Value: managedCfg.Config.InjectInto},
					); err != nil {
						return fmt.Errorf("managed inject sync failed: %w", err)
					}
				}
				return openAllAt(feature, featurePath, internal.ListBranchesAt(featurePath), func() error {
					return refuseOpenDuringReparent(ws, feature)
				})
			}

			// Handle --feature-dir: open the feature directory
			if featureDir {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --feature-dir")
				}
				feature := args[0]
				ws, err = managedTemplateWorkspaceForFeature(ws, feature)
				if err != nil {
					return err
				}
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				resolved, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					return resolveErr
				}
				path := resolved
				admission, err := featureRenameAdmissionAt(ws, feature)
				if err != nil {
					return err
				}
				defer func() { retErr = errors.Join(retErr, admission.Release()) }()
				managed, managedErr := internal.ManagedTemplateStatePresent(resolved)
				if managedErr != nil {
					return managedErr
				}
				var managedCfg resolvedManagedConfig
				if managed {
					managedCfg, err = resolveManagedConfig(ws)
					if err != nil {
						return err
					}
					if err := internal.ValidateManagedOrchestratorContext(
						ws, feature, path, managedCfg.AgentCommand,
					); err != nil {
						return err
					}
				}
				if _, err := os.Stat(path); os.IsNotExist(err) {
					return fmt.Errorf("feature not found: %s", feature)
				}
				// The resolved path is authoritative for this route. Refuse
				// before the no-agent fast path and before any success prose;
				// the intent wrapper below repeats the check after publishing
				// its race-closing launch intent.
				if err := refuseExternalOpenDuringMutation(feature, path); err != nil {
					return err
				}
				if noAgent {
					fmt.Printf("cd %s\n", path)
					return nil
				}
				return withExternalSessionLaunchIntent(path, feature, nil, true, func() error {
					return refuseExternalOpenDuringMutation(feature, path)
				}, func() error {
					fmt.Printf("Opening feature dir: %s\n", path)
					// Untracked: a feature directory is not a logical branch,
					// so no long-lived direct session record is created.
					return openDirect(directOpenOpts{
						Path: path, AgentCommand: managedCfg.AgentCommand,
					})
				})
			}

			// Normal mode: open a specific worktree
			context, branch, err := resolveOpenArgs(ws, args)
			if err != nil {
				return err
			}
			ws = context.Workspace
			feature := context.Feature
			admission, err := featureRenameAdmissionAt(ws, feature)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, admission.Release()) }()
			// §14.2a, after the picker has settled the identity: the exclusion
			// covers the 0-arg and 1-arg picker routes too.
			if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
				return rerr
			}

			featurePath := context.FeaturePath
			path := filepath.Join(featurePath, "worktrees", filepath.FromSlash(branch))
			resolvedFeaturePath := context.FeaturePath
			managed, managedErr := internal.ManagedTemplateStatePresent(resolvedFeaturePath)
			if managedErr != nil {
				return managedErr
			}
			if managed {
				featurePath = resolvedFeaturePath
			}

			if _, err := os.Stat(path); os.IsNotExist(err) {
				return fmt.Errorf("worktree not found: %s", path)
			}

			// Re-sync inject files
			injectTarget := internal.ResolveInjectInto("")
			var managedCfg resolvedManagedConfig
			if managed {
				managedCfg, err = resolveManagedConfig(ws)
				if err != nil {
					return err
				}
				injectTarget = managedCfg.Config.InjectInto
				if err := syncManagedAndLegacyInject(
					cmd, ws, feature, featurePath, branch, path,
					managedInjectTarget{Value: injectTarget},
				); err != nil {
					return fmt.Errorf("managed inject sync failed: %w", err)
				}
			} else if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return nil
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if managed {
					cfg = managedCfg.Config
				}
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				return openWithTmuxResolved(feature, branch, path, featurePath, managedCfg.AgentCommand, func() error {
					return refuseOpenDuringReparent(ws, feature)
				})
			}
			// Warn if there's a stale tmux session
			session := sanitizeSessionName(feature + "/" + branch)
			if sessionExists(session) {
				fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
				fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
			}
			return openDirect(directOpenOpts{
				Path:         path,
				Feature:      feature,
				Name:         branch,
				GitBranch:    resolveDirectGitBranch(featurePath, branch),
				FeaturePath:  featurePath,
				AgentCommand: managedCfg.AgentCommand,
				FinalGuard: func() error {
					return refuseOpenDuringReparent(ws, feature)
				},
			})
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Legacy human path guidance without launching an agent")
	cmd.Flags().BoolVar(&featureDir, "feature-dir", false, "Open the feature directory (orchestrator mode)")
	cmd.Flags().BoolVar(&all, "all", false, "Create tmux session with windows for all worktrees")
	cmd.Flags().BoolVar(&printPath, "print-path", false, "Print one verified absolute path without launching or changing state")
	cmd.Flags().StringVar(&command, "command", "", "Run one executable; literal child arguments follow a post-selector --")

	cmd = featureRenameAdmittedCommand(cmd)
	legacyRun := cmd.RunE
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		if !printPath && !cmd.Flags().Changed("command") {
			return legacyRun(cmd, args)
		}
		opts, err := parseExplicitOpen(cmd, args, printPath, command, featureDir, useTmux, noTmux, noAgent, all)
		if err != nil {
			return err
		}
		return runExplicitOpen(cmd, opts)
	}
	return cmd
}

func resolveOpenArgs(ws internal.Workspace, args []string) (resolvedFeatureContext, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		context, err := resolveFeatureContext(ws, args[0])
		return context, args[1], err
	case 1:
		feature = args[0]
		context, err := resolveFeatureContext(ws, feature)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		branches := internal.ListBranchesAt(context.FeaturePath)
		if len(branches) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		return context, branch, nil
	case 0:
		executionWS, resolveErr := managedTemplateExecutionWorkspace(ws)
		if resolveErr != nil {
			return resolvedFeatureContext{}, "", resolveErr
		}
		features, listErr := executionWS.ListFeaturesResolved()
		if listErr != nil {
			return resolvedFeatureContext{}, "", listErr
		}
		if len(features) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		context, err := resolveFeatureContext(executionWS, feature)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		branches := internal.ListBranchesAt(context.FeaturePath)
		if len(branches) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		return context, branch, nil
	}
	return resolvedFeatureContext{}, "", fmt.Errorf("unexpected args")
}

// openAll creates a tmux session with the feature dir as the first window
// and one window per active worktree.
// ExternalSessionLaunchIntentHook is a test-only seam after a tmux/all/feature
// launch intent is durable and before the final feature-mutation check.
var ExternalSessionLaunchIntentHook func() error

func withExternalSessionLaunchIntent(featurePath, feature string, names []string, featureWide bool, finalGuard, action func() error) (err error) {
	admission, err := internal.AcquireExternalFeatureAdmission(filepath.Dir(featurePath), feature)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, admission.Release()) }()
	token, err := internal.CreateExternalSessionIntent(featurePath, feature, names, featureWide)
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, internal.RemoveOwnedExternalSessionIntent(featurePath, token))
	}()
	if ExternalSessionLaunchIntentHook != nil {
		if err := ExternalSessionLaunchIntentHook(); err != nil {
			return err
		}
	}
	if finalGuard != nil {
		if err := finalGuard(); err != nil {
			return err
		}
	}
	if action == nil {
		return nil
	}
	return action()
}

func openAll(feature, featurePath string, finalGuard func() error) error {
	return openAllAt(feature, featurePath, internal.ListBranchesAt(featurePath), finalGuard)
}

func openAllAt(feature, featurePath string, branches []string, finalGuard func() error) error {
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}
	return withExternalSessionLaunchIntent(featurePath, feature, nil, true, finalGuard, func() error {
		if _, err := exec.LookPath("tmux"); err != nil {
			return fmt.Errorf("required tool %q not found in PATH", "tmux")
		}
		session := sanitizeSessionName(feature)
		if sessionExists(session) {
			fmt.Printf("Attaching to existing session: %s\n", session)
			return internal.Run("tmux", "attach", "-t", session)
		}

		fmt.Printf("Creating tmux session: %s\n", session)
		if err := internal.Run("tmux", "new-session", "-d", "-s", session, "-c", featurePath, "-n", "orchestrator"); err != nil {
			return err
		}

		for _, branch := range branches {
			wtPath := filepath.Join(featurePath, "worktrees", filepath.FromSlash(branch))
			if _, err := os.Stat(wtPath); os.IsNotExist(err) {
				continue
			}
			windowName := sanitizeSessionName(branch)
			_ = internal.RunSilent("tmux", "new-window", "-t", session, "-n", windowName, "-c", wtPath)
		}
		_ = internal.RunSilent("tmux", "select-window", "-t", session+":orchestrator")
		return internal.Run("tmux", "attach", "-t", session)
	})
}

func openWithTmux(feature, branch, path, featurePath string, finalGuard func() error) error {
	return openWithTmuxResolved(feature, branch, path, featurePath, "", finalGuard)
}

func openWithTmuxResolved(
	feature, branch, path, featurePath, agentCommand string,
	finalGuard func() error,
) error {
	return withExternalSessionLaunchIntent(featurePath, feature, []string{branch}, false, finalGuard, func() error {
		if _, err := exec.LookPath("tmux"); err != nil {
			return fmt.Errorf("required tool %q not found in PATH", "tmux")
		}
		session := sanitizeSessionName(feature + "/" + branch)
		if sessionExists(session) {
			fmt.Printf("Attaching to existing session: %s\n", session)
			return internal.Run("tmux", "attach", "-t", session)
		}

		agentCmd := agentCommand
		if agentCmd == "" {
			cfg := internal.LoadConfig()
			agentCmd = cfg.GetAgentCommand()
		}
		if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
			agentCmd += " -c"
		}

		fmt.Printf("Creating tmux session: %s\n", session)
		if err := internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path); err != nil {
			return err
		}
		fmt.Printf("Running: %s\n", agentCmd)
		if err := internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"); err != nil {
			return err
		}
		return internal.Run("tmux", "attach", "-t", session)
	})
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	return internal.SanitizeTmuxName(s)
}

func isClaudeAgent(cmd string) bool {
	fields := strings.Fields(cmd)
	if len(fields) == 0 {
		return false
	}
	base := fields[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

type explicitOpenOptions struct {
	feature, name         string
	printPath, featureDir bool
	executable            string
	args                  []string
	tmux, noTmux, tmuxSet bool
}

func explicitOpenSelectorCount(featureDir bool) int {
	if featureDir {
		return 1
	}
	return 2
}

// A marker before the required selector slots escapes options. Only a marker
// after those slots delimits child argv; a selector itself may be "--".
func splitExplicitOpenArgs(args []string, dash, count int) (selectors, child []string, childMarker bool, err error) {
	if dash < 0 {
		return args, nil, false, nil
	}
	if dash >= count {
		at := min(dash, len(args))
		return args[:at], args[at:], true, nil
	}
	if len(args) <= count {
		return args, nil, false, nil
	}
	if args[count] != "--" {
		return nil, nil, false, errors.New("child arguments require another -- immediately after option-escaped selectors")
	}
	return args[:count], args[count+1:], true, nil
}

func parseExplicitOpen(cmd *cobra.Command, args []string, printPath bool, executable string, featureDir, tmux, noTmux, noAgent, all bool) (explicitOpenOptions, error) {
	o := explicitOpenOptions{
		printPath: printPath, featureDir: featureDir, executable: executable,
		tmux: tmux, noTmux: noTmux, tmuxSet: cmd.Flags().Changed("tmux"),
	}
	commandSet := cmd.Flags().Changed("command")
	if printPath && commandSet {
		return o, errors.New("--print-path and --command are mutually exclusive")
	}
	if all || noAgent {
		return o, errors.New("--print-path and --command cannot be combined with --all or --no-agent")
	}
	if printPath && (cmd.Flags().Changed("tmux") || cmd.Flags().Changed("no-tmux")) {
		return o, errors.New("--print-path does not accept tmux launch flags")
	}
	if tmux && noTmux {
		return o, errors.New("--tmux and --no-tmux cannot both be enabled")
	}
	want := explicitOpenSelectorCount(featureDir)
	selectors, child, childMarker, err := splitExplicitOpenArgs(args, cmd.ArgsLenAtDash(), want)
	if err != nil {
		return o, err
	}
	if childMarker && !commandSet {
		return o, errors.New("only --command accepts a post-selector -- and child arguments")
	}
	o.args = append([]string(nil), child...)
	if len(selectors) != want {
		return o, errors.New("explicit open requires <feature> <logical-branch>, or <feature> --feature-dir; child arguments must follow --")
	}
	for _, value := range selectors {
		if value == "" || strings.ContainsRune(value, '\x00') {
			return o, errors.New("open selectors must be nonempty and contain no NUL")
		}
	}
	o.feature = selectors[0]
	if err := internal.GuardFeatureName("", o.feature); err != nil {
		return o, err
	}
	if !featureDir {
		o.name = selectors[1]
		if filepath.IsAbs(o.name) || filepath.Clean(o.name) != o.name ||
			o.name == "." || o.name == ".." || strings.HasPrefix(o.name, "../") ||
			strings.Contains(o.name, "\\") {
			return o, errors.New("logical branch must be a safe relative name")
		}
	}
	if commandSet {
		if executable == "" || strings.ContainsRune(executable, '\x00') {
			return o, errors.New("--command requires one nonempty executable without NUL")
		}
		for _, arg := range o.args {
			if strings.ContainsRune(arg, '\x00') {
				return o, errors.New("command arguments cannot contain NUL")
			}
		}
	}
	return o, nil
}

// Bind before admission or checkout activation. In particular, ErrDot is not
// permission to search the target directory instead of the caller's PATH.
func bindOpenExecutable(executable string) (string, error) {
	path, err := exec.LookPath(executable)
	if err != nil {
		return "", fmt.Errorf("resolve --command executable: %w", err)
	}
	return filepath.Abs(path)
}

type explicitOpenTarget struct {
	context resolvedFeatureContext
	path    string
	entry   internal.StackEntry
	info    os.FileInfo
}

func resolveExplicitOpenTarget(ws internal.Workspace, o explicitOpenOptions) (explicitOpenTarget, error) {
	var target explicitOpenTarget
	context, err := resolveFeatureContext(ws, o.feature)
	if err != nil {
		return target, err
	}
	target.context = context
	if err := verifyOpenFeatureDirectory(context); err != nil {
		return target, err
	}
	target.path = context.FeaturePath
	if !o.featureDir {
		if context.Workspace.Mode == internal.ModeExternal {
			target.path, err = internal.ResolveInjectWorktree(context.FeaturePath, o.name)
			if err != nil {
				return target, fmt.Errorf("resolve worktree %q: %w", o.name, err)
			}
			target.entry = internal.StackEntry{Name: o.name, Branch: resolveDirectGitBranch(context.FeaturePath, o.name)}
		} else {
			target.entry, err = internal.CheckoutCommandEntry(context.Workspace, context.FeaturePath, o.name)
			if err != nil {
				return target, err
			}
			target.path = context.Workspace.RepoRoot
			if o.printPath {
				if err := internal.CheckoutCommandCurrentEntry(context.Workspace, target.entry); err != nil {
					return target, err
				}
			}
		}
	}
	target.path, err = filepath.Abs(target.path)
	if err != nil {
		return target, err
	}
	target.info, err = os.Lstat(target.path)
	if err != nil {
		return target, err
	}
	if target.info.Mode()&os.ModeSymlink != 0 || !target.info.IsDir() {
		return target, errors.New("open target must be a real directory, not a symlink")
	}
	return target, nil
}

func verifyOpenFeatureDirectory(context resolvedFeatureContext) error {
	rel, err := filepath.Rel(context.Workspace.MetadataRoot, context.FeaturePath)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return errors.New("feature directory escapes its workspace")
	}
	path := context.Workspace.MetadataRoot
	for _, part := range strings.Split(rel, string(filepath.Separator)) {
		path = filepath.Join(path, part)
		info, err := os.Lstat(path)
		if err != nil {
			return fmt.Errorf("feature directory: %w", err)
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return fmt.Errorf("feature directory %s is not a real directory", path)
		}
	}
	return nil
}

func explicitOpenMutationGuard(context resolvedFeatureContext) error {
	if context.Workspace.Mode == internal.ModeCheckout {
		return internal.CheckoutSessionMutationPreconditions(context.Workspace)
	}
	if _, err := featureRenameRouteAdmission(internal.ModeExternal, context.Feature, context.FeaturePath, true); err != nil {
		return err
	}
	if err := refuseExternalOpenDuringMutation(context.Feature, context.FeaturePath); err != nil {
		return err
	}
	for _, path := range []string{internal.SyncStatePath(context.FeaturePath), internal.SyncRunStatePath(context.FeaturePath)} {
		if _, err := os.Lstat(path); !errors.Is(err, os.ErrNotExist) {
			if err != nil {
				return fmt.Errorf("sync evidence could not be verified: %w", err)
			}
			return fmt.Errorf("sync recovery is pending for %q; use tws sync %s --continue (or --abort)", context.Feature, context.Feature)
		}
	}
	return nil
}

// OpenPrintPathBeforeOutputHook is a test-only seam before the final read-only
// namespace and target checks.
var OpenPrintPathBeforeOutputHook func() error

func runExplicitOpen(cmd *cobra.Command, o explicitOpenOptions) (retErr error) {
	var command []string
	if !o.printPath {
		path, err := bindOpenExecutable(o.executable)
		if err != nil {
			return err
		}
		command = append([]string{path}, o.args...)
	}
	ws, err := internal.RequireWorkspace()
	if err != nil {
		return err
	}
	if ws.Mode == internal.ModeCheckout && o.featureDir && o.tmux {
		return errors.New("--feature-dir --command does not support tmux in checkout mode; use --no-tmux or a logical branch")
	}
	selectedRoot := ""
	if ws.Mode == internal.ModeExternal {
		selectedRoot, err = filepath.Abs(internal.TwsRoot())
		if err != nil {
			return err
		}
		if _, err := featureRenameSelectionAdmission(selectedRoot, o.feature, true); err != nil {
			return err
		}
	}
	target, err := resolveExplicitOpenTarget(ws, o)
	if err != nil {
		return err
	}
	guard := func() error {
		if _, err := featureRenameSelectionAdmission(selectedRoot, o.feature, true); err != nil {
			return err
		}
		if err := explicitOpenMutationGuard(target.context); err != nil {
			return err
		}
		current, err := resolveExplicitOpenTarget(ws, o)
		if err != nil {
			return err
		}
		if current.path != target.path || current.context.FeaturePath != target.context.FeaturePath ||
			current.entry != target.entry || !os.SameFile(current.info, target.info) {
			return errors.New("open target changed during admission; retry after inspecting the workspace")
		}
		return nil
	}
	if err := guard(); err != nil {
		return err
	}
	if o.printPath {
		if strings.ContainsFunc(target.path, func(r rune) bool { return r < 0x20 || r == 0x7f }) {
			return errors.New("cannot print a path containing control characters")
		}
		if OpenPrintPathBeforeOutputHook != nil {
			if err := OpenPrintPathBeforeOutputHook(); err != nil {
				return err
			}
		}
		if err := guard(); err != nil {
			return err
		}
		_, err := fmt.Fprintln(cmd.OutOrStdout(), target.path)
		return err
	}

	cfg, err := resolveManagedConfig(target.context.Workspace)
	if err != nil {
		return err
	}
	useTmux := o.tmux
	if !o.featureDir && !o.tmuxSet && !o.noTmux && cfg.Config.UseTmux != nil {
		useTmux = *cfg.Config.UseTmux
	}
	if o.noTmux {
		useTmux = false
	}
	var tmux internal.SessionTmuxRunner
	if useTmux {
		if _, err := exec.LookPath("tmux"); err != nil {
			return errors.New("required tool \"tmux\" not found in PATH")
		}
		tmux = internal.RealSessionTmuxRunner{}
		name := explicitCommandSessionName(target, o)
		if err := internal.RefuseCommandTmuxCollision(tmux, name); err != nil {
			return err
		}
	}
	selection, err := featureRenameSelectionAdmission(selectedRoot, o.feature, false)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, selection.Release()) }()
	admission, err := featureRenameAdmissionAt(target.context.Workspace, o.feature)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, admission.Release()) }()
	finalGuard := func() error {
		return errors.Join(selection.Verify(), admission.Verify(), guard())
	}
	if target.context.Workspace.Mode == internal.ModeCheckout {
		if o.featureDir {
			return internal.WithCheckoutCommandLaunchIntent(target.context.Workspace, func() error {
				if err := finalGuard(); err != nil {
					return err
				}
				if err := internal.ValidateManagedOrchestratorContext(target.context.Workspace, o.feature, target.context.FeaturePath, cfg.AgentCommand); err != nil {
					return err
				}
				return internal.CheckoutFeatureDirSessionPreconditions(target.context.Workspace)
			}, func() error {
				return openDirectCommand(directCommandOptions{Path: target.path, Command: command})
			})
		}
		return internal.OpenCheckoutCommand(target.context.Workspace, o.feature, target.entry, command,
			checkoutDirectCommandRunner{}, tmux, cfg.Config.InjectInto, finalGuard)
	}
	return withExternalCommandIntent(target, o, func(token string) error {
		if err := finalGuard(); err != nil {
			return err
		}
		if err := verifyCommandIntent(target, o, token); err != nil {
			return err
		}
		if useTmux {
			if err := internal.RefuseCommandTmuxCollision(tmux, explicitCommandSessionName(target, o)); err != nil {
				return err
			}
		}
		if o.featureDir {
			if err := internal.ValidateManagedOrchestratorContext(target.context.Workspace, o.feature, target.context.FeaturePath, cfg.AgentCommand); err != nil {
				return err
			}
		} else if err := injectOpenCommand(target, o, cfg.Config.InjectInto, token); err != nil {
			return err
		}
		launchGuard := func() error {
			return errors.Join(finalGuard(), verifyCommandIntent(target, o, token))
		}
		if err := launchGuard(); err != nil {
			return err
		}
		if useTmux {
			return internal.RunExternalTmuxCommand(tmux, explicitCommandSessionName(target, o), target.path, command, token)
		}
		opts := directCommandOptions{Path: target.path, Command: command, FinalGuard: launchGuard}
		if !o.featureDir {
			opts.FeaturePath, opts.Feature, opts.Name = target.context.FeaturePath, o.feature, o.name
			opts.GitBranch = target.entry.Branch
		}
		return openDirectCommand(opts)
	})
}

func explicitCommandSessionName(target explicitOpenTarget, o explicitOpenOptions) string {
	if target.context.Workspace.Mode == internal.ModeCheckout {
		return internal.CheckoutAgentSessionName(target.context.Workspace.StableID, o.feature, o.name)
	}
	if o.featureDir {
		return internal.ExternalFeatureTmuxSessionName(o.feature)
	}
	return internal.ExternalTmuxSessionName(o.feature, o.name)
}

func withExternalCommandIntent(target explicitOpenTarget, o explicitOpenOptions, action func(string) error) (err error) {
	names := []string{o.name}
	token, err := internal.CreateExternalSessionIntent(target.context.FeaturePath, o.feature, names, commandIntentFeatureWide(o))
	if err != nil {
		return err
	}
	defer func() {
		if verifyErr := verifyCommandIntent(target, o, token); verifyErr != nil {
			err = errors.Join(err, verifyErr)
			return
		}
		err = errors.Join(err, internal.RemoveOwnedExternalSessionIntent(target.context.FeaturePath, token))
	}()
	if ExternalSessionLaunchIntentHook != nil {
		if err := ExternalSessionLaunchIntentHook(); err != nil {
			return err
		}
	}
	return action(token)
}

func commandIntentFeatureWide(o explicitOpenOptions) bool {
	// Existing branch intents trim edge whitespace. Broaden the reservation
	// rather than changing a verified legacy logical identity.
	return o.featureDir || strings.TrimSpace(o.name) != o.name
}

func verifyCommandIntent(target explicitOpenTarget, o explicitOpenOptions, token string) error {
	intents, _, err := internal.LoadExternalSessionIntents(target.context.FeaturePath, o.feature, []string{o.name}, nil)
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if intent.State == internal.DirectRecordOK && intent.Record.Token == token &&
			intent.Record.OwnerPID == os.Getpid() &&
			((commandIntentFeatureWide(o) && intent.Record.Scope == internal.ExternalSessionIntentFeature) ||
				(!commandIntentFeatureWide(o) && intent.Record.Scope == internal.ExternalSessionIntentBranches &&
					len(intent.Record.Names) == 1 && intent.Record.Names[0] == o.name)) {
			return nil
		}
	}
	return errors.New("command launch intent ownership changed; preserve the remaining evidence")
}

func injectOpenCommand(target explicitOpenTarget, o explicitOpenOptions, into, token string) (retErr error) {
	fp := target.context.FeaturePath
	managed, err := internal.ManagedTemplateStatePresent(fp)
	if err != nil {
		return err
	}
	if !managed {
		return internal.InjectFiles(fp, target.path, into)
	}
	state, err := internal.LoadManagedTemplateState(fp)
	if err != nil {
		return err
	}
	if _, ok := state.Roles[string(internal.ManagedTemplateRoleWorktree)]; !ok {
		return internal.InjectFiles(fp, target.path, into)
	}
	plan, err := internal.PlanManagedTemplate(internal.ManagedTemplatePlanRequest{
		Workspace: target.context.Workspace, Feature: o.feature, FeaturePath: fp,
		Roles:               []internal.ManagedTemplateRole{internal.ManagedTemplateRoleWorktree},
		LinkMaterializeOnly: true, OnlyWorktree: o.name, InjectInto: into,
	})
	if err != nil {
		return err
	}
	if noop, err := verifiedManagedInjectNoop(plan, []managedInjectDestination{{path: target.path}}); err != nil || noop {
		return err
	}
	held, err := acquireManagedTemplateReservations([]*internal.ManagedTemplatePlan{plan}, nil, nil)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, releaseManagedTemplateReservations(held)) }()
	// The entry intent is ours, but every other live/unverifiable runtime
	// still excludes a managed update. The direct record is created later.
	if err := verifyCommandIntent(target, o, token); err != nil {
		return err
	}
	blocking, _, err := internal.GuardDirectSessionsFor(fp, directRecordTargetForBranch(o.feature, o.name), nil)
	if err != nil {
		return err
	}
	intents, _, err := internal.LoadExternalSessionIntents(fp, o.feature, []string{o.name}, nil)
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if intent.State != internal.DirectRecordOK || intent.Record.Token != token {
			return errors.New("another session intent blocks managed command injection")
		}
	}
	if len(blocking) > 0 {
		return errors.New("live or unverifiable direct sessions block managed command injection")
	}
	probe := managedTemplateTmuxProbe
	if probe == nil {
		probe = internal.RealTmuxInventory{}
	}
	snapshot := probe.Snapshot()
	if snapshot.Err != nil {
		return snapshot.Err
	}
	if snapshot.Sessions[internal.ExternalTmuxSessionName(o.feature, o.name)] ||
		snapshot.Sessions[internal.ExternalFeatureTmuxSessionName(o.feature)] {
		return errors.New("an existing tmux session blocks managed command injection")
	}
	replanned, err := internal.ReplanManagedTemplate(plan)
	if err != nil {
		return err
	}
	if err := internal.ValidateManagedTemplateReplan(plan, replanned, held.template[0]); err != nil {
		return err
	}
	if err := internal.ApplyManagedTemplatePlan(replanned); err != nil {
		return err
	}
	excluded, err := internal.ManagedTemplateOwnedWorktreePaths(fp)
	if err != nil {
		return err
	}
	return internal.InjectFilesExcluding(fp, target.path, "", excluded)
}

