// criterion34GateCommands is §22.34's own list, verbatim: the full gate
// suite, in the spec's order.
var criterion34GateCommands = []string{
	"gofmt -l internal cmd",
	"go test ./... -count=1",
	"go vet ./...",
	"golangci-lint run ./...",
	"make build",
	"git diff --check",
	"tpatch feature deps --validate-all",
}

// criterion34FocusedSelectors is §22.34's "focused gates while implementing"
// block: the -run selectors an implementer is told to use. A selector that
// matches no declared test in the corpus is a documentation lie, so each is
// asserted non-vacuous below.
var criterion34FocusedSelectors = []string{
	"TestRebasePlan|TestPlanFingerprint|TestPlanSchema|TestRemainingRebaseEntries",
	"TestSyncPlan|TestPlanGuard|TestSyncNoFlag_",
	"TestSyncScoped_|TestCheckoutSyncModes_",
}

// declaredTestNames parses every `func TestXxx(` declaration under the two
// packages this feature touches, by scanning the source rather than by
// running anything.
func declaredTestNames(t *testing.T) []string {
	t.Helper()
	re := regexp.MustCompile(`(?m)^func (Test[A-Za-z0-9_]*)\(`)
	var names []string
	for _, dir := range []string{"internal", "internal/cli"} {
		entries, err := os.ReadDir(filepath.Join(docsRepoRoot, dir))
		if err != nil {
			t.Fatalf("read %s: %v", dir, err)
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), "_test.go") {
				continue
			}
			data, err := os.ReadFile(filepath.Join(docsRepoRoot, dir, e.Name()))
			if err != nil {
				t.Fatalf("read %s/%s: %v", dir, e.Name(), err)
			}
			for _, m := range re.FindAllStringSubmatch(string(data), -1) {
				names = append(names, m[1])
			}
		}
	}
	if len(names) == 0 {
		t.Fatal("found no declared test functions at all; the scan is broken")
	}
	return names
}

// TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous is
// §22.34's executable owner. The suite itself is run by the outer harness;
// what a test inside the repository can and must own is that every gate the
// criterion names really EXISTS here and that none of its selectors is
// vacuous:
//
//   - `gofmt -l internal cmd` is executed for real and must report nothing;
//   - `make build` names a real Makefile target, and the Makefile also
//     declares the `test` and `lint` targets the suite leans on;
//   - `git diff --check` is executed for real against the working tree;
//   - each focused `-run` selector matches at least one declared test in
//     `internal/` or `internal/cli/`;
//   - the frozen-path gate of criterion 1 still holds: `TestSyncNoFlag_`
//     matches, and the fixture directory still contains exactly 126 files.
//
// A gate command list that drifts from the spec's own block, or a selector
// that stops matching anything, fails here.
func TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous(t *testing.T) {
	if len(criterion34GateCommands) != 7 {
		t.Fatalf("§22.34 lists 7 gate commands, this table has %d", len(criterion34GateCommands))
	}

	t.Run("gofmt_reports_nothing", func(t *testing.T) {
		out, err := exec.Command("gofmt", "-l",
			filepath.Join(docsRepoRoot, "internal"), filepath.Join(docsRepoRoot, "cmd")).CombinedOutput()
		if err != nil {
			t.Fatalf("gofmt -l internal cmd: %v\n%s", err, out)
		}
		if strings.TrimSpace(string(out)) != "" {
			t.Fatalf("gofmt -l internal cmd reported unformatted files:\n%s", out)
		}
	})

	t.Run("make_targets_exist", func(t *testing.T) {
		makefile := readRepoDoc(t, "Makefile")
		for _, target := range []string{"build:", "test:", "lint:"} {
			if !regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(target)).MatchString(makefile) {
				t.Fatalf("Makefile declares no %q target, but §22.34's suite invokes it", target)
			}
		}
	})

	t.Run("git_diff_check_is_clean", func(t *testing.T) {
		cmd := exec.Command("git", "diff", "--check")
		cmd.Dir = docsRepoRoot
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git diff --check failed: %v\n%s", err, out)
		}
	})

	t.Run("focused_selectors_are_non_vacuous", func(t *testing.T) {
		names := declaredTestNames(t)
		for _, selector := range criterion34FocusedSelectors {
			re, err := regexp.Compile(selector)
			if err != nil {
				t.Fatalf("selector %q does not compile: %v", selector, err)
			}
			matched := 0
			for _, n := range names {
				if re.MatchString(n) {
					matched++
				}
			}
			if matched == 0 {
				t.Fatalf("focused selector %q matches no declared test: the documented gate is vacuous", selector)
			}
		}
	})

	t.Run("frozen_path_gate_still_holds", func(t *testing.T) {
		names := declaredTestNames(t)
		noflag := 0
		for _, n := range names {
			if strings.HasPrefix(n, "TestSyncNoFlag_") {
				noflag++
			}
		}
		if noflag == 0 {
			t.Fatal("no TestSyncNoFlag_ test is declared; §22 criterion 1's frozen-path gate would be vacuous")
		}
		files := 0
		root := filepath.Join(docsRepoRoot, "internal", "cli", "testdata", "sync_noflag")
		if err := filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if !d.IsDir() {
				files++
			}
			return nil
		}); err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
		if files != 126 {
			t.Fatalf("internal/cli/testdata/sync_noflag holds %d files, want the frozen 126", files)
		}
	})
}

// ---------------------------------------------------------------------------
// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves
// ---------------------------------------------------------------------------

// bannedDocPhrases are the three substrings spec.md §22.33a forbids: an
// unqualified "--plan mutates nothing" claim, a bare `from` scope-value
// spelling, and a ninth warning kind. None of these are flag literals, so
// they are checked separately from TestSyncPlanDocs_FlagWorkflowSurfacesCarryAllFiveLiterals.
var bannedDocPhrases = []string{"without mutating anything", "scope=from", "nine warning"}

// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves implements spec.md
// §22.33a's negative check exactly as scoped: "exactly two halves, and no
// third". Half (a) is a corpus grep over README.md, CHANGELOG.md, docs/ and
// assets/ only — never internal/, never cmd/, never a _test.go file, never
// a testdata directory — because tests legitimately contain every banned
// phrase as negative fixtures, so an unscoped grep would forbid the very
// tests that enforce this criterion. Half (b) is the exact tws sync --help
// output, asserted never to contain any of the three phrases as a
// substring.
func TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves(t *testing.T) {
	t.Run("prose-and-assets", func(t *testing.T) {
		// This walk is built to match the spec's corpus by construction: it
		// only ever reads README.md, CHANGELOG.md and files under docs/ and
		// assets/, and it skips any directory named "testdata" that it
		// encounters. It never touches internal/, cmd/, or any _test.go
		// file — those simply are not among the four roots below.
		roots := []string{
			filepath.Join(docsRepoRoot, "README.md"),
			filepath.Join(docsRepoRoot, "CHANGELOG.md"),
			filepath.Join(docsRepoRoot, "docs"),
			filepath.Join(docsRepoRoot, "assets"),
		}
		var files []string
		for _, root := range roots {
			info, err := os.Stat(root)
			if err != nil {
				t.Fatalf("stat %s: %v", root, err)
			}
			if !info.IsDir() {
				files = append(files, root)
				continue
			}
			if err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				if d.IsDir() {
					if d.Name() == "testdata" {
						return filepath.SkipDir
					}
					return nil
				}
				files = append(files, path)
				return nil
			}); err != nil {
				t.Fatalf("walking %s: %v", root, err)
			}
		}
		if len(files) < 5 {
			t.Fatalf("corpus walk found only %d files, expected the README, CHANGELOG and docs/+assets/ trees", len(files))
		}

		for _, path := range files {
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("reading %s: %v", path, err)
			}
			content := string(data)
			for _, phrase := range bannedDocPhrases {
				if strings.Contains(content, phrase) {
					t.Errorf("%s must not contain the banned phrase %q", path, phrase)
				}
			}
		}

		// Positive control: the Go tree legitimately contains a banned
		// phrase as a negative-fixture string (internal/rebase_plan_render_test.go
		// asserts a rendered Policy line never prints "scope=from"). This
		// file is deliberately outside every root above; if it had been
		// included, this exact check would fail — which is the reason
		// spec.md §22.33a scopes the corpus away from the Go tree at all,
		// rather than an assumption this test takes on faith.
		goFixture := filepath.Join("..", "rebase_plan_render_test.go")
		data, err := os.ReadFile(goFixture)
		if err != nil {
			t.Fatalf("reading %s: %v", goFixture, err)
		}
		if !strings.Contains(string(data), "scope=from") {
			t.Fatalf("%s no longer contains the banned literal \"scope=from\" as a negative-fixture string; the corpus-exclusion rationale (spec.md §22.33a) has nothing left to guard against", goFixture)
		}
	})

	t.Run("help-output", func(t *testing.T) {
		stdout, _, exit := runSyncExecute(t, "--help")
		if exit != 0 {
			t.Fatalf("tws sync --help must exit 0, got %d", exit)
		}
		for _, phrase := range bannedDocPhrases {
			if strings.Contains(stdout, phrase) {
				t.Errorf("tws sync --help must not contain the banned phrase %q:\n%s", phrase, stdout)
			}
		}
	})
}

package internal

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func CheckoutCommandEntry(ws Workspace, featurePath, name string) (StackEntry, error) {
	info, err := os.Lstat(StackPath(featurePath))
	if err != nil || !info.Mode().IsRegular() {
		return StackEntry{}, errors.New("checkout stack metadata is missing or is not a regular file")
	}
	stack, err := LoadStack(featurePath)
	if err != nil {
		return StackEntry{}, err
	}
	var found StackEntry
	for _, entry := range stack.Branches {
		if entry.Name == name {
			if found.Name != "" {
				return StackEntry{}, fmt.Errorf("duplicate logical branch %q", name)
			}
			found = entry
		}
	}
	if found.Name == "" {
		return found, fmt.Errorf("logical branch %q is not in the selected feature", name)
	}
	if found.Archived || found.Repo != "" {
		return found, errors.New("checkout open requires an active single-repository logical branch")
	}
	if _, err := sessionGitOutput(ws.RepoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+found.GitBranch()); err != nil {
		return found, fmt.Errorf("local checkout branch %q is missing", found.GitBranch())
	}
	return found, nil
}

func CheckoutCommandCurrentEntry(ws Workspace, entry StackEntry) error {
	current, err := sessionGitOutput(ws.RepoRoot, "symbolic-ref", "--quiet", "HEAD")
	if err != nil || current != "refs/heads/"+entry.GitBranch() {
		return fmt.Errorf("path query requires logical entry %q to be the current attached checkout; it does not switch branches", entry.Name)
	}
	return nil
}

type checkoutCommandOwnership struct {
	state     *CheckoutAgentSession
	lock      checkoutSessionIntentSnapshot
	stateInfo os.FileInfo
	stateData []byte
}

func verifyCheckoutCommandIntent(ws Workspace, expected checkoutSessionIntentSnapshot, token string) error {
	current, present, err := loadCheckoutSessionIntentSnapshot(ws)
	if err != nil || !present {
		return errors.Join(errors.New("checkout command launch intent is missing or unverifiable"), err)
	}
	owner, err := current.decodeOwner()
	if err != nil || owner.Token != token || owner.PID != os.Getpid() ||
		!os.SameFile(expected.dirInfo, current.dirInfo) ||
		!os.SameFile(expected.ownerInfo, current.ownerInfo) ||
		!bytes.Equal(expected.ownerBytes, current.ownerBytes) {
		return errors.New("checkout command launch intent ownership changed; preserve the remaining evidence")
	}
	return nil
}

// CheckoutCommandIntentCaptureHook is a test-only seam after acquisition and
// before the launcher can establish its initial ownership snapshot.
var CheckoutCommandIntentCaptureHook func() error

func captureCheckoutCommandIntent(ws Workspace, token string) (checkoutSessionIntentSnapshot, error) {
	if CheckoutCommandIntentCaptureHook != nil {
		if err := CheckoutCommandIntentCaptureHook(); err != nil {
			return checkoutSessionIntentSnapshot{}, fmt.Errorf("checkout command intent capture failed; preserve the remaining evidence: %w", err)
		}
	}
	snapshot, present, err := loadCheckoutSessionIntentSnapshot(ws)
	if err != nil || !present {
		return checkoutSessionIntentSnapshot{}, errors.Join(
			errors.New("checkout command intent could not be captured; preserve the remaining evidence"), err)
	}
	if err := verifyCheckoutCommandIntent(ws, snapshot, token); err != nil {
		return checkoutSessionIntentSnapshot{}, err
	}
	return snapshot, nil
}

// WithCheckoutCommandLaunchIntent protects a branchless command without
// inventing a branch session. Unlike legacy open, it verifies its intent
// before effects and makes the directory publications durable.
func WithCheckoutCommandLaunchIntent(ws Workspace, finalCheck, launch func() error) (retErr error) {
	if err := commandSessionStateDirectories(ws, false); err != nil {
		return err
	}
	token, err := acquireAgentSessionLock(ws, RealSessionTmuxRunner{})
	if err != nil {
		return err
	}
	snapshot, err := captureCheckoutCommandIntent(ws, token)
	if err != nil {
		return err
	}
	defer func() {
		if err := verifyCheckoutCommandIntent(ws, snapshot, token); err != nil {
			retErr = errors.Join(retErr, err)
			return
		}
		retErr = errors.Join(retErr, removeCheckoutSessionIntentSnapshot(ws, snapshot))
	}()
	if CheckoutSessionLaunchIntentHook != nil {
		if err := CheckoutSessionLaunchIntentHook(); err != nil {
			return err
		}
	}
	if finalCheck != nil {
		if err := finalCheck(); err != nil {
			return err
		}
	}
	if err := verifyCheckoutCommandIntent(ws, snapshot, token); err != nil {
		return err
	}
	for _, dir := range []string{sessionLockDir(ws), filepath.Join(ws.MetadataRoot, "state"), ws.MetadataRoot} {
		if err := syncDir(dir); err != nil {
			return err
		}
	}
	if launch == nil {
		return nil
	}
	return launch()
}

func loadCheckoutCommandOwnership(ws Workspace, state *CheckoutAgentSession) (*checkoutCommandOwnership, error) {
	if state.SchemaVersion != checkoutSessionSchema || state.Stage != DirectStageCommand ||
		state.LockToken == "" || state.WorkspaceID != ws.StableID || state.RepoDir != ws.RepoRoot ||
		(state.Mode != AgentSessionDirect && state.Mode != AgentSessionTmux) ||
		state.Feature == "" || state.Name == "" || state.GitBranch == "" || state.OriginalBranch == "" ||
		state.OriginalHEAD == "" || state.PID <= 0 {
		return nil, errors.New("checkout command state identity is invalid; preserve it for manual reconciliation")
	}
	if err := validateFeatureName(state.Feature); err != nil {
		return nil, err
	}
	if state.Mode == AgentSessionTmux && state.TmuxSession != CheckoutAgentSessionName(ws.StableID, state.Feature, state.Name) ||
		state.Mode == AgentSessionDirect && state.TmuxSession != "" {
		return nil, errors.New("checkout command transport identity is invalid; state retained")
	}
	lock, present, err := loadCheckoutSessionIntentSnapshot(ws)
	if err != nil || !present {
		return nil, errors.Join(errors.New("checkout command lock is missing or unverifiable; state retained"), err)
	}
	owner, err := lock.decodeOwner()
	if err != nil || owner.Token != state.LockToken || owner.PID != state.PID {
		return nil, errors.New("checkout command lock ownership changed; state retained")
	}
	if err := commandSessionStateDirectories(ws, false); err != nil {
		return nil, err
	}
	info, err := os.Lstat(sessionStatePath(ws))
	if err != nil || !info.Mode().IsRegular() {
		return nil, errors.Join(errors.New("checkout command record is missing or not a regular file; state retained"), err)
	}
	data, err := os.ReadFile(sessionStatePath(ws))
	if err != nil {
		return nil, err
	}
	expected, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return nil, err
	}
	if !bytes.Equal(data, expected) {
		return nil, errors.New("checkout command record changed; state retained")
	}
	return &checkoutCommandOwnership{state: state, lock: lock, stateInfo: info, stateData: data}, nil
}

func (owned *checkoutCommandOwnership) verify(ws Workspace) error {
	current, err := loadCheckoutCommandOwnership(ws, owned.state)
	if err != nil {
		return err
	}
	if !os.SameFile(owned.lock.dirInfo, current.lock.dirInfo) ||
		!os.SameFile(owned.lock.ownerInfo, current.lock.ownerInfo) ||
		!bytes.Equal(owned.lock.ownerBytes, current.lock.ownerBytes) ||
		!os.SameFile(owned.stateInfo, current.stateInfo) ||
		!bytes.Equal(owned.stateData, current.stateData) {
		return errors.New("checkout command ownership changed; preserve the record and lock")
	}
	return nil
}

func commandSessionStateDirectories(ws Workspace, create bool) error {
	for _, path := range []string{ws.MetadataRoot, filepath.Join(ws.MetadataRoot, "state"), sessionStateDir(ws)} {
		info, err := os.Lstat(path)
		if errors.Is(err, os.ErrNotExist) {
			if create {
				if err := os.Mkdir(path, 0700); err != nil {
					return err
				}
			}
			continue
		}
		if err != nil {
			return err
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return errors.New("checkout command state directory is not a real directory")
		}
	}
	return nil
}

// CheckoutCommandStateWriteHook is a test-only persistence failure seam.
var CheckoutCommandStateWriteHook func() error

func createCheckoutCommandState(ws Workspace, state *CheckoutAgentSession) error {
	if CheckoutCommandStateWriteHook != nil {
		if err := CheckoutCommandStateWriteHook(); err != nil {
			return err
		}
	}
	if err := commandSessionStateDirectories(ws, true); err != nil {
		return err
	}
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	// Exclusive publication cannot replace a foreign record appearing after
	// admission. A failed write keeps evidence and never permits child effects.
	file, err := os.OpenFile(sessionStatePath(ws), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	_, writeErr := file.Write(data)
	syncErr := file.Sync()
	closeErr := file.Close()
	if err := errors.Join(writeErr, syncErr, closeErr); err != nil {
		return err
	}
	for _, dir := range []string{sessionStateDir(ws), sessionLockDir(ws), filepath.Join(ws.MetadataRoot, "state"), ws.MetadataRoot} {
		if err := syncDir(dir); err != nil {
			return err
		}
	}
	return nil
}

func checkoutCommandGitOperation(repo string) (bool, error) {
	for _, name := range []string{"rebase-merge", "rebase-apply", "MERGE_HEAD", "CHERRY_PICK_HEAD", "REVERT_HEAD"} {
		path, err := sessionGitOutput(repo, "rev-parse", "--git-path", name)
		if err != nil {
			return false, err
		}
		if !filepath.IsAbs(path) {
			path = filepath.Join(repo, path)
		}
		if _, err := os.Lstat(path); err == nil {
			return true, nil
		} else if !errors.Is(err, os.ErrNotExist) {
			return false, err
		}
	}
	return false, nil
}

func checkoutCommandPreconditions(ws Workspace, feature string, entry StackEntry) error {
	if active, err := checkoutCommandGitOperation(ws.RepoRoot); err != nil {
		return fmt.Errorf("Git operation state is unverifiable: %w", err)
	} else if active {
		return errors.New("another Git operation is in progress")
	}
	return CheckoutSessionPreconditions(ws, feature, entry)
}

// OpenCheckoutCommand uses the existing one-owner session record and lock.
// A non-nil tmux selects tmux; a nil runner selects the ordinary direct runner.
func OpenCheckoutCommand(ws Workspace, feature string, entry StackEntry, command []string, runner SessionAgentRunner, tmux SessionTmuxRunner, into string, finalGuard func() error) (retErr error) {
	if len(command) == 0 || !filepath.IsAbs(command[0]) {
		return errors.New("command executable must be bound before checkout activation")
	}
	for _, arg := range command {
		if strings.ContainsRune(arg, '\x00') {
			return errors.New("command argv cannot contain NUL")
		}
	}
	if err := commandSessionStateDirectories(ws, false); err != nil {
		return err
	}
	if err := checkoutCommandPreconditions(ws, feature, entry); err != nil {
		return err
	}
	name := CheckoutAgentSessionName(ws.StableID, feature, entry.Name)
	if tmux != nil {
		if err := RefuseCommandTmuxCollision(tmux, name); err != nil {
			return err
		}
	}
	token, err := acquireAgentSessionLock(ws, tmux)
	if err != nil {
		return err
	}
	initialLock, err := captureCheckoutCommandIntent(ws, token)
	if err != nil {
		return err
	}
	release := true
	defer func() {
		if release {
			if err := verifyCheckoutCommandIntent(ws, initialLock, token); err != nil {
				retErr = errors.Join(retErr, err)
				return
			}
			retErr = errors.Join(retErr, removeCheckoutSessionIntentSnapshot(ws, initialLock))
		}
	}()
	if CheckoutSessionLaunchIntentHook != nil {
		if err := CheckoutSessionLaunchIntentHook(); err != nil {
			return err
		}
	}
	if finalGuard != nil {
		if err := finalGuard(); err != nil {
			return err
		}
	}
	if err := verifyCheckoutCommandIntent(ws, initialLock, token); err != nil {
		return err
	}
	if err := checkoutCommandPreconditions(ws, feature, entry); err != nil {
		return err
	}
	if tmux != nil {
		if err := RefuseCommandTmuxCollision(tmux, name); err != nil {
			return err
		}
	}
	if err := verifyCheckoutCommandIntent(ws, initialLock, token); err != nil {
		return err
	}
	original, err := sessionCurrentBranch(ws.RepoRoot)
	if err != nil {
		return err
	}
	head, err := sessionHEAD(ws.RepoRoot)
	if err != nil {
		return err
	}
	links, err := PlanCheckoutSessionLinks(ws, feature, into)
	if err != nil {
		return err
	}
	excludes, err := newCommandExcludes(ws.RepoRoot, links)
	if err != nil {
		return err
	}
	state := &CheckoutAgentSession{
		SchemaVersion: checkoutSessionSchema, WorkspaceID: ws.StableID, Feature: feature,
		Name: entry.Name, GitBranch: entry.GitBranch(), OriginalBranch: original, OriginalHEAD: head,
		Mode: AgentSessionDirect, PID: os.Getpid(), Stage: DirectStageCommand,
		StartedAt: time.Now().UTC().Format(time.RFC3339), RepoDir: ws.RepoRoot,
		Links: links, ExcludeEntries: excludes, LockToken: token,
	}
	if tmux != nil {
		state.Mode, state.TmuxSession = AgentSessionTmux, name
	}
	if err := createCheckoutCommandState(ws, state); err != nil {
		if _, statErr := os.Lstat(sessionStatePath(ws)); !errors.Is(statErr, os.ErrNotExist) {
			release = false
			return fmt.Errorf("command state publication failed; preserve the record and lock for inspection (no command ran): %w", err)
		}
		return err
	}
	release = false
	owned, err := loadCheckoutCommandOwnership(ws, state)
	if err != nil {
		return err
	}
	if !os.SameFile(initialLock.dirInfo, owned.lock.dirInfo) || !os.SameFile(initialLock.ownerInfo, owned.lock.ownerInfo) ||
		!bytes.Equal(initialLock.ownerBytes, owned.lock.ownerBytes) {
		return errors.New("checkout command lock changed during state publication; state retained")
	}
	failBeforeLaunch := func(cause error) error {
		return errors.Join(cause, finishCheckoutCommandSession(ws, owned, true))
	}
	if err := owned.verify(ws); err != nil {
		return err
	}
	if finalGuard != nil {
		if err := finalGuard(); err != nil {
			return failBeforeLaunch(err)
		}
	}
	if err := CheckoutSessionMutationPreconditions(ws); err != nil {
		return failBeforeLaunch(err)
	}
	if err := sessionSwitch(ws.RepoRoot, entry.GitBranch()); err != nil {
		return failBeforeLaunch(err)
	}
	if _, err := ApplyCheckoutSessionLinks(ws.RepoRoot, links); err != nil {
		return failBeforeLaunch(err)
	}
	if err := owned.verify(ws); err != nil {
		return err
	}
	if finalGuard != nil {
		if err := finalGuard(); err != nil {
			return failBeforeLaunch(err)
		}
	}
	if err := CheckoutSessionMutationPreconditions(ws); err != nil {
		return failBeforeLaunch(err)
	}
	if tmux != nil {
		return runCheckoutTmuxCommand(ws, owned, command, tmux)
	}
	if runner == nil {
		runner = RealSessionAgentRunner{}
	}
	runErr := runner.Run(ws.RepoRoot, command)
	return errors.Join(wrapSessionErr("command", runErr), finishCheckoutCommandSession(ws, owned, false))
}

func runCheckoutTmuxCommand(ws Workspace, owned *checkoutCommandOwnership, command []string, runner SessionTmuxRunner) error {
	tmux, err := commandTmuxRunner(runner)
	if err != nil {
		return errors.Join(err, finishCheckoutCommandSession(ws, owned, true))
	}
	state := owned.state
	if err := RefuseCommandTmuxCollision(runner, state.TmuxSession); err != nil {
		// A session appeared after activation. It may already be writing this
		// checkout; neither restoration nor killing is safe.
		return fmt.Errorf("tmux collision after admission; checkout command state retained: %w", err)
	}
	startErr := tmux.NewCommandSession(state.TmuxSession, ws.RepoRoot, command, state.LockToken)
	present, probeErr := tmux.OwnedCommandSession(state.TmuxSession, state.LockToken)
	if probeErr != nil {
		return errors.Join(startErr, fmt.Errorf("tmux startup ownership is uncertain; checkout state retained: %w", probeErr))
	}
	if !present {
		return errors.Join(startErr, finishCheckoutCommandSession(ws, owned, false))
	}
	if startErr != nil {
		return fmt.Errorf("tmux startup failed but the owned command is live; checkout state retained; inspect or use tws close: %w", startErr)
	}
	if err := owned.verify(ws); err != nil {
		return err
	}
	attachErr := tmux.AttachCommandSession(state.TmuxSession, state.LockToken)
	present, probeErr = tmux.OwnedCommandSession(state.TmuxSession, state.LockToken)
	if probeErr != nil {
		return errors.Join(attachErr, probeErr)
	}
	if present {
		if attachErr != nil {
			return fmt.Errorf("tmux attach failed but the command remains active; use tws close %s %s: %w", state.Feature, state.Name, attachErr)
		}
		return owned.verify(ws)
	}
	return errors.Join(wrapSessionErr("tmux attach (child exit status unavailable)", attachErr), finishCheckoutCommandSession(ws, owned, false))
}

func newCommandExcludes(repo string, links []SessionContextLink) ([]string, error) {
	data, err := os.ReadFile(filepath.Join(repo, ".git", "info", "exclude"))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	existing := map[string]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		existing[line] = true
	}
	var owned []string
	for _, link := range links {
		rel, err := filepath.Rel(repo, link.Path)
		if err != nil {
			return nil, err
		}
		name := filepath.ToSlash(rel)
		if !existing[name] {
			owned = append(owned, name)
		}
	}
	return owned, nil
}

func finishCheckoutCommandSession(ws Workspace, owned *checkoutCommandOwnership, unstarted bool) error {
	retained := func(err error) error {
		return fmt.Errorf("cannot restore checkout command; session state retained: %w; commit/stash work or reconcile the recorded branch/ownership, then use tws close", err)
	}
	if err := owned.verify(ws); err != nil {
		return retained(err)
	}
	state := owned.state
	current, err := sessionCurrentBranch(ws.RepoRoot)
	if err != nil {
		return retained(errors.New("HEAD is detached"))
	}
	if current != state.GitBranch && (!unstarted || current != state.OriginalBranch) {
		return retained(errors.New("the attached branch changed"))
	}
	if err := CheckoutSessionMutationPreconditions(ws); err != nil {
		return retained(err)
	}
	if active, err := checkoutCommandGitOperation(ws.RepoRoot); err != nil {
		return retained(err)
	} else if active {
		return retained(errors.New("another Git operation is in progress"))
	}
	dirty, err := sessionDirty(ws.RepoRoot)
	if err != nil {
		return retained(err)
	}
	if dirty {
		return retained(errors.New("working tree is dirty"))
	}
	if state.OriginalBranch != state.GitBranch {
		head, err := sessionGitOutput(ws.RepoRoot, "rev-parse", "--verify", "refs/heads/"+state.OriginalBranch)
		if err != nil || head != state.OriginalHEAD {
			return retained(errors.New("original branch HEAD changed or disappeared"))
		}
	}
	for _, link := range state.Links {
		if err := ensureSessionDestination(ws.RepoRoot, link.Path); err != nil {
			return retained(err)
		}
		if trackedPath(ws.RepoRoot, link.Path) {
			return retained(fmt.Errorf("context link %s became tracked; preserve it", link.Path))
		}
		target, err := os.Readlink(link.Path)
		if errors.Is(err, os.ErrNotExist) && unstarted {
			continue
		}
		if err != nil || target != link.Target {
			return retained(fmt.Errorf("context link %s changed or disappeared", link.Path))
		}
	}
	if err := owned.verify(ws); err != nil {
		return retained(err)
	}
	for _, link := range state.Links {
		if err := os.Remove(link.Path); err != nil && (!unstarted || !errors.Is(err, os.ErrNotExist)) {
			return retained(err)
		}
	}
	if len(state.ExcludeEntries) > 0 {
		if err := removeSessionExcludes(ws.RepoRoot, state.ExcludeEntries); err != nil {
			return retained(err)
		}
	}
	if current != state.OriginalBranch {
		if err := sessionSwitch(ws.RepoRoot, state.OriginalBranch); err != nil {
			return retained(err)
		}
		if head, err := sessionHEAD(ws.RepoRoot); err != nil || head != state.OriginalHEAD {
			return retained(errors.New("original branch HEAD changed during restoration"))
		}
		if current, err := sessionCurrentBranch(ws.RepoRoot); err != nil || current != state.OriginalBranch {
			return retained(errors.New("attached branch changed during restoration"))
		}
		if dirty, err := sessionDirty(ws.RepoRoot); err != nil || dirty {
			return retained(errors.Join(errors.New("checkout became dirty or unverifiable during restoration"), err))
		}
	}
	if err := owned.verify(ws); err != nil {
		return retained(err)
	}
	if err := os.Remove(sessionStatePath(ws)); err != nil {
		return retained(err)
	}
	if err := syncDir(sessionStateDir(ws)); err != nil {
		return fmt.Errorf("checkout restored and command record removed, but cleanup durability failed; preserve the remaining lock: %w", err)
	}
	if err := releaseAgentSessionLock(ws, state.LockToken); err != nil {
		return fmt.Errorf("checkout restored but command lock cleanup failed: %w", err)
	}
	return syncDir(filepath.Join(ws.MetadataRoot, "state"))
}

func closeCheckoutCommandSession(ws Workspace, state *CheckoutAgentSession, runner SessionTmuxRunner) error {
	owned, err := loadCheckoutCommandOwnership(ws, state)
	if err != nil {
		return err
	}
	if state.Mode == AgentSessionDirect {
		if state.PID > 0 && processAlive(state.PID) {
			return errors.New("direct checkout command is still active; exit it before closing")
		}
	} else {
		tmux, err := commandTmuxRunner(runner)
		if err != nil {
			return err
		}
		present, err := tmux.OwnedCommandSession(state.TmuxSession, state.LockToken)
		if err != nil {
			return err
		}
		if present {
			if err := owned.verify(ws); err != nil {
				return err
			}
			if err := tmux.KillCommandSession(state.TmuxSession, state.LockToken); err != nil {
				return err
			}
			if present, err := tmux.OwnedCommandSession(state.TmuxSession, state.LockToken); err != nil || present {
				return errors.Join(errors.New("tmux command termination could not be confirmed; state retained"), err)
			}
		}
	}
	return finishCheckoutCommandSession(ws, owned, false)
}

package internal

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

type commandTestRunner func(string, []string) error

func (f commandTestRunner) Run(dir string, command []string) error { return f(dir, command) }

type commandTestTmux struct {
	*testTmux
	tokens    map[string]string
	args      []string
	dir       string
	exists    func(string) error
	onCreate  func(string, string) error
	onAttach  func(string) error
	onOwned   func(string) error
	onKill    func(string) error
	createErr error
}

func newCommandTestTmux() *commandTestTmux {
	return &commandTestTmux{testTmux: newTestTmux(), tokens: map[string]string{}}
}

func (f *commandTestTmux) CommandSessionExists(name string) (bool, error) {
	if f.exists != nil {
		if err := f.exists(name); err != nil {
			return false, err
		}
	}
	return f.sessions[name], nil
}

func (f *commandTestTmux) NewCommandSession(name, dir string, command []string, token string) error {
	f.sessions[name], f.tokens[name] = true, token
	f.args, f.dir = append([]string(nil), command...), dir
	f.created = append(f.created, name)
	if f.onCreate != nil {
		if err := f.onCreate(name, token); err != nil {
			return err
		}
	}
	return f.createErr
}

func (f *commandTestTmux) OwnedCommandSession(name, token string) (bool, error) {
	if f.onOwned != nil {
		if err := f.onOwned(name); err != nil {
			return false, err
		}
	}
	if f.sessions[name] && f.tokens[name] != token {
		return false, errors.New("foreign tmux session owner")
	}
	return f.sessions[name], nil
}

func (f *commandTestTmux) AttachCommandSession(name, token string) error {
	if _, err := f.OwnedCommandSession(name, token); err != nil {
		return err
	}
	if f.onAttach != nil {
		return f.onAttach(name)
	}
	return f.attachErr
}

func (f *commandTestTmux) KillCommandSession(name, token string) error {
	if _, err := f.OwnedCommandSession(name, token); err != nil {
		return err
	}
	if f.onKill != nil {
		if err := f.onKill(name); err != nil {
			return err
		}
	}
	return f.KillSession(name)
}

func assertCheckoutCommandRetained(t *testing.T, ws Workspace, branch string) {
	t.Helper()
	if !HasCheckoutAgentSession(ws) {
		t.Fatal("command state was lost")
	}
	if _, err := os.Lstat(sessionLockDir(ws)); err != nil {
		t.Fatal("command lock was lost", err)
	}
	if got, _ := sessionCurrentBranch(ws.RepoRoot); got != branch {
		t.Fatalf("current branch=%q want=%q", got, branch)
	}
}

func assertCheckoutCommandCleaned(t *testing.T, ws Workspace) {
	t.Helper()
	if HasCheckoutAgentSession(ws) {
		t.Fatal("command state remains")
	}
	if _, err := os.Lstat(sessionLockDir(ws)); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("command lock remains: %v", err)
	}
	if got, _ := sessionCurrentBranch(ws.RepoRoot); got != "main" {
		t.Fatalf("not restored: %q", got)
	}
}

func TestCheckoutCommandDirectDurabilityAndObservation(t *testing.T) {
	repo, ws, entry := setupSessionRepo(t)
	context := filepath.Join(ws.FeaturePath("feature"), "inject", "context")
	if err := os.WriteFile(context, []byte("configured context"), 0600); err != nil {
		t.Fatal(err)
	}
	command := []string{"/absolute/editor", "", "literal ; argv", "line\nbreak", "--option"}
	calls := 0
	runner := commandTestRunner(func(dir string, args []string) error {
		calls++
		if dir != repo || !reflect.DeepEqual(args, command) {
			t.Fatalf("dir=%q argv=%q", dir, args)
		}
		state, err := LoadCheckoutAgentSession(ws)
		if err != nil || state.Stage != DirectStageCommand || state.GitBranch != entry.GitBranch() {
			t.Fatalf("state=%+v err=%v", state, err)
		}
		if _, err := loadCheckoutCommandOwnership(ws, state); err != nil {
			t.Fatal("state is not owned before child effects", err)
		}
		if got := gitS(t, repo, "branch", "--show-current"); got != entry.GitBranch() {
			t.Fatal("not activated", got)
		}
		if target, err := os.Readlink(filepath.Join(repo, "context")); err != nil || target != context {
			t.Fatalf("context target=%q err=%v", target, err)
		}
		report, err := BuildAgentStatusScoped(ws, "", "feature", nil)
		if err != nil {
			t.Fatal(err)
		}
		observation := report.Workspace.CheckoutSession
		if observation == nil || !observation.StageRecognized || observation.Stage == nil ||
			*observation.Stage != DirectStageCommand || observation.Agent != nil ||
			observation.AgentState != AgentStateUnknown || observation.Presence != PresencePresent {
			t.Fatalf("observation=%+v", observation)
		}
		raw, err := json.Marshal(report)
		if err != nil || bytes.Contains(raw, []byte(command[2])) || bytes.Contains(raw, []byte(state.LockToken)) {
			t.Fatalf("status leaked command/token or failed: %v", err)
		}
		if _, err := acquireAgentSessionLock(ws, newTestTmux()); err == nil {
			t.Fatal("second checkout owner admitted")
		}
		if err := CloseCheckoutSession(ws, "feature", entry.Name, nil); err == nil {
			t.Fatal("close interrupted a live direct command")
		}
		return nil
	})
	if err := OpenCheckoutCommand(ws, "feature", entry, command, runner, nil, "", nil); err != nil {
		t.Fatal(err)
	}
	if calls != 1 {
		t.Fatalf("child calls=%d", calls)
	}
	assertCheckoutCommandCleaned(t, ws)
	if _, err := os.Lstat(filepath.Join(repo, "context")); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("context remains: %v", err)
	}
}

func TestCheckoutCommandNonzeroRestores(t *testing.T) {
	_, ws, entry := setupSessionRepo(t)
	childErr := errors.New("exit status 9")
	err := OpenCheckoutCommand(ws, "feature", entry, []string{"/editor"}, commandTestRunner(func(string, []string) error {
		return childErr
	}), nil, "", nil)
	if !errors.Is(err, childErr) {
		t.Fatalf("nonzero result=%v", err)
	}
	assertCheckoutCommandCleaned(t, ws)
}

func TestCheckoutCommandPersistencePrecedesActivationAndEffects(t *testing.T) {
	_, ws, entry := setupSessionRepo(t)
	failure := errors.New("disk full")
	CheckoutCommandStateWriteHook = func() error { return failure }
	t.Cleanup(func() { CheckoutCommandStateWriteHook = nil })
	calls := 0
	err := OpenCheckoutCommand(ws, "feature", entry, []string{"/editor"}, commandTestRunner(func(string, []string) error {
		calls++
		return nil
	}), nil, "", nil)
	if !errors.Is(err, failure) || calls != 0 {
		t.Fatalf("err=%v calls=%d", err, calls)
	}
	assertCheckoutCommandCleaned(t, ws)
}

func TestCheckoutCommandForeignStateAtPublication(t *testing.T) {
	_, ws, entry := setupSessionRepo(t)
	foreign := []byte(`{"foreign":"do not replace"}`)
	CheckoutCommandStateWriteHook = func() error {
		if err := os.MkdirAll(sessionStateDir(ws), 0700); err != nil {
			return err
		}
		return os.WriteFile(sessionStatePath(ws), foreign, 0600)
	}
	t.Cleanup(func() { CheckoutCommandStateWriteHook = nil })
	runner := &testAgent{}
	err := OpenCheckoutCommand(ws, "feature", entry, []string{"/editor"}, runner, nil, "", nil)
	if err == nil || runner.calls != 0 {
		t.Fatalf("err=%v calls=%d", err, runner.calls)
	}
	got, err := os.ReadFile(sessionStatePath(ws))
	if err != nil || !bytes.Equal(got, foreign) {
		t.Fatalf("foreign state overwritten: %q %v", got, err)
	}
	assertCheckoutCommandRetained(t, ws, "main")
}

func TestCheckoutCommandUnsafeCompletionRetainsEvidence(t *testing.T) {
	for _, change := range []string{"dirty", "detached", "branch", "original-head", "record", "lock", "link", "tracked-link"} {
		t.Run(change, func(t *testing.T) {
			repo, ws, entry := setupSessionRepo(t)
			inject := filepath.Join(ws.FeaturePath("feature"), "inject", "context")
			if err := os.WriteFile(inject, []byte("context"), 0600); err != nil {
				t.Fatal(err)
			}
			var recordAfter []byte
			wantBranch := entry.GitBranch()
			runner := commandTestRunner(func(string, []string) error {
				switch change {
				case "dirty":
					return os.WriteFile(filepath.Join(repo, "README"), []byte("user changes"), 0644)
				case "detached":
					gitS(t, repo, "switch", "--detach")
					wantBranch = ""
				case "branch":
					gitS(t, repo, "switch", "main")
					wantBranch = "main"
				case "original-head":
					gitS(t, repo, "commit", "--allow-empty", "-m", "new")
					gitS(t, repo, "branch", "-f", "main", "HEAD")
				case "record":
					state, err := LoadCheckoutAgentSession(ws)
					if err != nil {
						return err
					}
					state.OriginalBranch = "foreign"
					if err := SaveCheckoutAgentSession(ws, state); err != nil {
						return err
					}
					recordAfter, _ = os.ReadFile(sessionStatePath(ws))
				case "lock":
					return os.WriteFile(sessionLockOwnerPath(ws), []byte(`{"token":"foreign","pid":1}`), 0600)
				case "link":
					if err := os.Remove(filepath.Join(repo, "context")); err != nil {
						return err
					}
					return os.Symlink("foreign", filepath.Join(repo, "context"))
				case "tracked-link":
					gitS(t, repo, "add", "-f", "context")
					gitS(t, repo, "commit", "-m", "preserve context link")
				}
				return nil
			})
			err := OpenCheckoutCommand(ws, "feature", entry, []string{"/editor"}, runner, nil, "", nil)
			if err == nil || !strings.Contains(err.Error(), "retained") {
				t.Fatalf("unsafe cleanup err=%v", err)
			}
			assertCheckoutCommandRetained(t, ws, wantBranch)
			if change != "link" {
				if target, err := os.Readlink(filepath.Join(repo, "context")); err != nil || target != inject {
					t.Fatalf("context was touched during unsafe cleanup: %q %v", target, err)
				}
			}
			if recordAfter != nil {
				got, _ := os.ReadFile(sessionStatePath(ws))
				if !bytes.Equal(got, recordAfter) {
					t.Fatal("foreign record changed")
				}
			}
		})
	}
}

