					t.Fatal(err)
				}
				ownerInfo, err = os.Lstat(kept)
				if err != nil {
					t.Fatal(err)
				}
				return nil
			}
			t.Cleanup(func() { CheckoutCommandIntentCaptureHook = nil })
			runner := &testAgent{}
