	return err == nil
}

func CheckoutAgentSessionPresence(ws Workspace) (bool, error) {
	_, err := os.Stat(sessionStatePath(ws))
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return true, nil
